--
-- Table structure for table `purchase_orders`
--

DROP TABLE IF EXISTS `purchase_orders`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `purchase_orders` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `id_sales_order` bigint DEFAULT NULL,
  `purchase_method` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vehicle_registration` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `hp_finance_provider` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `hire_purchase_starting_date` date NOT NULL,
  `hp_interest_per_annum` double DEFAULT NULL,
  `hp_deposit_amount` double DEFAULT NULL,
  `hp_term` int DEFAULT NULL,
  `documentation_fees_pu` double DEFAULT NULL,
  `final_fees` double DEFAULT NULL,
  `other_fees` double DEFAULT NULL,
  `price_otr` double NOT NULL,
  `monthly_payment` double DEFAULT NULL,
  `final_payment` double DEFAULT NULL,
  `hp_interest_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vehicle_manufactur` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vehicle_model` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `vehicle_variant` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `basic_list_price` double NOT NULL,
  `residual_value` double NOT NULL,
  `colour` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `min_contract_price_satu` double NOT NULL,
  `min_contract_price_dua` double NOT NULL,
  `service_maintenance` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `mot_due_date` date NOT NULL,
  `rfl_due_date` date NOT NULL,
  `service_schedule_miles` double DEFAULT NULL,
  `service_schedule_years` double DEFAULT NULL,
  `last_service_mileage` double DEFAULT NULL,
  `last_service_date` date DEFAULT NULL,
  `financing_amount` double DEFAULT NULL,
  `regular_monthly_payment` double DEFAULT NULL,
  `status_next_step` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vehicle_tracking` double DEFAULT NULL,
  `sum_docdepoth` double DEFAULT NULL,
  `tgl_available` date DEFAULT NULL,
  `stock_status` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `eta` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=262 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

